def split_lowerstring(s):
    """
    Splits a string at lowercase letters.

    Args:
        s (str): The input string.

    Returns:
        list: A list of substrings split at lowercase letters.
    """
    result = []
    current = ''
    for char in s:
        if char.islower():
            if current:
                result.append(current)
                current = ''
        else:
            current += char
    if current:
        result.append(current)
    return result

def remove_dirty_chars(s1, s2):
    """
    This function removes characters from the first string which are present in the second string.

    Args:
        s1 (str): The original string.
        s2 (str): The string containing characters to be removed.

    Returns:
        str: The string with characters from s2 removed.

    Raises:
        TypeError: If either of the inputs is not a string.
        ValueError: If the input strings contain non-alphabetic characters.
    """
    # Check if the inputs are strings
    if not isinstance(s1, str) or not isinstance(s2, str):
        raise TypeError('Both inputs must be strings.')

    # Check if the input strings only contain alphabetic characters
    if not s1.isalpha() or not s2.isalpha():
        raise ValueError('Input strings must only contain alphabetic characters.')

    # Convert the second string to a set for efficient lookups
